\label{prop: relax max principle}
    Suppose $\boldsymbol{x}$ is a stationary point of $\bar F$ with $\bar F(\boldsymbol{x})>0$, and let $\mathbf w$ attain the minimum in \eqref{eq:relaxed-objective}.

    Suppose also that $k$ is ETP.

    Then $\Delta\leq0$, every distinct particle location is active, with positive total weight, and, for all $j=1,\dots,N$,

    \begin{equation*}
        \Delta'(x_j)=0,
        \qquad
        \Delta''(x_j)<0.
    \end{equation*}

    Further, all particles lie in the convex hull of $\operatorname{supp}(P^*)$.

\label{thm: relaxbound}
Suppose the kernel is ETP and the problem is well specified with $P^*$ supported on $K$ points.

If $N\geq K$, then $\bar F$ has no spurious local minima, and every spurious stationary point is unstable under the unweighted particle gradient flow.

\label{thm: relaxepsbound}
Let $D>0$ and $\varepsilon>0$.

There exists a finite threshold $N_\varepsilon(D)$ such that, uniformly over all target distributions with compact support of diameter at most $D$, whenever $N>N_\varepsilon(D)$ every local minimum of $\bar F$ satisfies

\begin{equation*}
    \operatorname{MMD}(P,P^*)<\varepsilon.
\end{equation*}

Moreover, every stationary point with $\operatorname{MMD}(P,P^*)\geq\varepsilon$ is unstable under the unweighted particle gradient flow.

\label{thm: SimpEpsBound}
Let $D>0$ and $\varepsilon>0$.

There exists a finite threshold $N_\varepsilon(D)$ such that, uniformly over all target distributions with compact support of diameter at most $D$, whenever $N>N_\varepsilon(D)$, every local minimum of $F$ over $\mathbf w\in\Delta^{N-1}$ and $\boldsymbol{x}\in\mathbb R^N$ satisfies

\begin{equation*}
    \operatorname{MMD}(P,P^*)<\varepsilon.
\end{equation*}

Moreover, every stationary point with $\operatorname{MMD}(P,P^*)\geq\varepsilon$ is unstable under the unweighted particle gradient flow.

\label{prop: cpos}
    Suppose we are at a stationary point of $F$ with $F(\mathbf{w}, \boldsymbol{x}) > 0$.

    Then $0<c<1$.

\label{prop: MMDFourierSplit}
Let $P,P^*$ be probability measures on $\mathbb R^d$, let $\rho=P-P^*$, and suppose $k$ is continuous, translation invariant, and has positive spectral density.

Then, writing $\Delta=\mu_P-\mu_{P^*}$, for every $\nu>0$ it holds that

\begin{align*}
    \operatorname{MMD}^2(P^*,P)
    \leq&
    \frac{\|\Delta\|_1^2}{(2\pi)^d}
    \int_{|\omega|\leq\nu}\frac{1}{\hat k(\omega)}\,\mathrm d\omega\\
    &+
    \frac{\|\rho\|_{\mathrm{TV}}^2}{(2\pi)^d}
    \int_{|\omega|>\nu}\hat k(\omega)\,\mathrm d\omega.
\end{align*}

In particular, for the one-dimensional Gaussian kernel with $2\sigma^2=1$,

\begin{equation*}
    \operatorname{MMD}^2(P,P^*)
    \leq
    \tfrac{\|\Delta\|_1^2}{\pi}\operatorname{erfi}\left(\tfrac{\nu}{2}\right)
    +
    4\operatorname{erfc}\left(\tfrac{\nu}{2}\right).
\end{equation*}
where $\operatorname{erfi}(z)=\frac{2}{\sqrt{\pi}}\int_0^z e^{t^2}\,\mathrm dt$, $\operatorname{erfc}(z)=\frac{2}{\sqrt{\pi}}\int_z^\infty e^{-t^2}\,\mathrm dt$ denote the imaginary error function and complementary error function, respectively.

\label{prop: NUpperBound}
A positive lower bound on the KKT level $c$ gives an upper bound on the number $A$ of distinct active particle locations.

One such bound is

\begin{align*}
    A
    \leq&
    \frac{2-c}{c}\log\left(\frac{2(c+2)}{c}\right)
    +
    \frac{e}{2}
    \left(\frac{8-5c}{c}\right)^2
    \log\left(\frac{2}{c}\right).
\end{align*}

\label{prop: neighbourhoodmiss}
Suppose that the problem is well specified, with $P^*=\sum_{j=1}^K w_j^*\delta_{x_j^*}$.

Then there exists $r(P^*)>0$ such that every spurious stationary point satisfies

\begin{equation}
    \max_j\min_i|x_i-x_j^*|
    \geq
    r(P^*).
\end{equation}

\label{prop: MMDholebound}
Suppose a target atom is missed by a neighbourhood of radius $r$ as in Prop.~\ref{prop: neighbourhoodmiss}.

Then

\begin{equation*}
    \operatorname{MMD}(P,P^*)
    \geq
    \frac{[w^*-(ar)^{-2m}]_+}{C(a,m)},
\end{equation*}

where $[u]_+=\max\{u,0\}$, $w^*=\min_jw_j^*$, and one may take 
\begin{equation}
    C(a,m)=\frac{\sqrt{\pi}}{a}e^{\frac12m^2a^2}, \qquad m\in\mathbb N_{\geq1}, \qquad a>0.
\end{equation}

Thus, choosing $a,m$ such that $(ar)^{-2m}<w^*$ gives a strictly positive lower bound on the MMD.

For a Hilbert space $\mathcal{H}$ of real-valued functions on $\mathcal{X}$, a function $k: \mathcal{X} \times \mathcal{X} \to \mathbb{R}$ is a reproducing kernel of $\mathcal{H}$ if

    \begin{enumerate}
        \item $k(x, \cdot) \in \mathcal{H}$ for all $x \in \mathcal{X}$;

        \item $\langle f, k(x, \cdot) \rangle_\mathcal{H} = f(x)$ for all $f \in \mathcal{H}$ and all $x \in \mathcal{X}$.

    \end{enumerate}

    In this case, $\mathcal{H}$ is called a Reproducing Kernel Hilbert Space (RKHS).

Let $k$ be a kernel, and $P$ be a probability distribution.

Then the (kernel) \emph{mean embedding} is defined by

    \begin{equation*}
        \mu_P(t) = \mathbb{E}_{x \sim P} k(x, t).
    \end{equation*}

Let $k$ be a kernel, and $P, Q$ be probability distributions.

Then the \emph{maximum mean discrepancy} (MMD) is defined by

    \begin{equation*}
        \operatorname{MMD}^2(P,Q) = \vert \vert \mu_P  - \mu_Q \vert \vert_\mathcal{H}^2.
    \end{equation*}

For a twice continuously differentiable kernel $k(x, x')$ with associated RKHS $\mathcal{F}$ and feature map $\varphi(x)$, and for $f \in \mathcal{F}$, we have

    \begin{equation*}
        \frac{d}{dx}f(x) = \langle f, \frac{d}{dx}\varphi(x)\rangle_\mathcal{F}, \qquad \langle \frac{d}{dx}\varphi(x), \varphi(x') \rangle_{\mathcal{F}} = \frac{d}{dx}k(x, x').
    \end{equation*}

The Gaussian kernel with bandwidth $\sigma$ is, for $x, y$ real vectors in some common space,

\begin{equation*}
    k_\sigma(x, y) = \exp\biggl(-\frac{\vert \vert x - y \vert \vert^2}{2\sigma^2}\biggr).
\end{equation*}

A function $f(x,y)$ of two real variables, $x$ ranging over $X$ and $y$ ranging over $Y$, is said to be totally positive of order $k$ ($TP_k$) if for all $x_1 < \ldots < x_m, y_1 < \ldots < y_m (x_i \in X, y_j \in Y)$, and all $1 \le m \le k$,

    \begin{equation}
        f \begin{pmatrix} x_1, \ldots, x_m\\y_1, \ldots, y_m \end{pmatrix} = \begin{vmatrix} f(x_1, y_1) & \ldots &f(x_1, y_m)\\ \vdots && \vdots\\ f(x_m, y_1) & \ldots & f(x_m, y_m) \end{vmatrix} \ge 0.
    \end{equation}

    Additionally, if all indicated derivatives exist, and $X, Y$ represent open intervals on the line, then for $1 \le n \le k$,

    \begin{equation}
        \label{TPnonstrict}
        \begin{vmatrix} f(x, y) & \ldots &\frac{\partial^{n-1}}{\partial y^{n-1}}f(x, y)\\ \vdots && \vdots\\ \frac{\partial^{n-1}}{\partial x^{n-1}}f(x, y) & \ldots & \frac{\partial^{2n-2}}{\partial x^{n-1} \partial y^{n-1}}f(x, y) \end{vmatrix} \ge 0.
    \end{equation}

\label{def: Variation deimishing}

    Let $V(g)$ denote the number of variations of sign of a function $g(x)$ as $x$ traverses the real line from left to right.

    Let $h(x)$ be given by the absolutely convergent integral

    \begin{equation}
        \label{convergenttpintegral}
        h(x) = \int f(x, w)g(w)d\sigma(w),
    \end{equation}

    where $f(x, w)$ is $TP_k$, $\sigma(w)$ is a non-negative $\sigma$-finite measure and $V(g) \le k-1$.

    Suppose also that $h(x)$ is $k$ times continuously differentiable, the interchange of integral and derivative is permissible in \eqref{convergenttpintegral}, and \eqref{TPnonstrict} holds strictly.

    Suppose $h \not\equiv 0$.

    Let $Z(h)$ denote the number of zeros of $h(x)$, counting multiplicities.

    Then $Z(h) \le V(g)$.

A sequence of functions $\phi_1, \ldots, \phi_n$ is referred to as a Chebyshev system on the interval $[a, b]$ if each of them is continuous and the determinant

\begin{equation*}
    \begin{vmatrix} \phi_1(x_1) & \ldots & \phi_1(x_n)\\ \vdots & & \vdots\\ \phi_n(x_1) & \ldots & \phi_n(x_n) \end{vmatrix}
\end{equation*}

is nonzero for any sequence of points $a \le x_1 < \ldots < x_n \le b$.

Equivalently, any nontrivial linear combination of the functions has at most $n-1$ distinct zeros.

Given a set of functions $\phi_1, \ldots, \phi_n$ which are continuously differentiable as needed on an interval $[a, b]$, and given a sequence of ordered points $a \le x_1 \le  \ldots \le x_n \le b$, define the sequence $m_1, \ldots, m_n$ by

    \begin{equation}
        \label{msequenceforet}
        \begin{aligned} m_1 = 0, \qquad m_j = \begin{cases} 0 & x_j \neq x_{j-1}\\ m_{j-1} + 1 & x_j = x_{j-1} \end{cases}.\\ \end{aligned}
    \end{equation}

    Let the matrix $C(x_1, \ldots, x_n) = [c_{ij}]$ be defined by the formula

    \begin{equation*}
        c_{ij} = \frac{d^{m_j}\phi_i}{dx^{m_j}}(x_j).
    \end{equation*}

    Then $\phi_1, \ldots, \phi_n$ is an extended Chebyshev system on $[a, b]$ if $\det(C(x_1, \ldots, x_n))$ is nonzero for all such sequences $x_i$.

\label{prop: jenzerocount}

    Let $R > 0$.

    Let $\delta  > 1$.

    Let $\Omega$ be an open set that contains the closure of a disc $D_{\delta R}$ and suppose that $f$ is holomorphic in $\Omega$ with $f(0) \neq 0$.

    Let $\mathbf{n}_f(r)$ denote the number of zeros (counting multiplicity) of $f$ in the disc of radius $r$.

    Assume that $\vert f(x + iy) \vert \le A_fe^{B_fy^2}$.

    Then

    \begin{equation*}
        \mathbf{n}_{f} (R) \le \frac{\log\bigl(\frac{A_f}{\vert f(0) \vert}\bigr) + \frac{1}{2}B_f\delta^2R^2}{\log(\delta)}.
    \end{equation*}

By Jensen's formula \citep[e.g., pg. 137][]{stein2010complex}, we have that

    \begin{align*}
        {\frac{1}{2\pi} \int_{0}^{2\pi} \log \vert f(\delta Re^{i\theta}) \vert d\theta - \log \vert f(0) \vert} &= \int_{0}^{\delta R} \frac{{\mathbf{n}_{f}}(r)}{r}dr \ge \int_{R}^{\delta R} \frac{{\mathbf{n}_{f}}(r)}{r} dr \ge  {\mathbf{n}_{f}} (R) \log(\delta).
    \end{align*}

    By the assumed bound, we have $\vert f(\delta Re^{i\theta})\vert \le A_fe^{B_f\delta^2 R^2\sin^2(\theta)}$.

    Thus, integrating and substituting into the previous bound, it follows that

    \begin{align*}
        \mathbf{n}_{f} (R) &\le \frac{\log\bigl(\frac{A_f}{\vert f(0) \vert}\bigr) + \frac{1}{2}B_f\delta^2R^2}{\log(\delta)}. \qedhere
    \end{align*}

First, the interpolation conditions follow by considering the matrix

    \begin{equation*}
        M(\boldsymbol{x^*},\boldsymbol{\bar{x}}) = \begin{bmatrix} k(\boldsymbol{x^*},\boldsymbol{\bar{x}}) & \partial_2k(\boldsymbol{x^*},\boldsymbol{\bar{x}})\\ \partial_1k(\boldsymbol{x^*},\boldsymbol{\bar{x}}) & \partial_1\partial_2k(\boldsymbol{x^*},\boldsymbol{\bar{x}}) \end{bmatrix}.
    \end{equation*}

    In particular, it suffices to find coefficients $\boldsymbol{\alpha},\boldsymbol{\beta}$ satisfying

    \begin{equation*}
        M(\boldsymbol{x^*},\boldsymbol{\bar{x}})\begin{bmatrix} \boldsymbol{\alpha}\\ \boldsymbol{\beta} \end{bmatrix} = \begin{bmatrix} \mathbf{1}\\ \mathbf{0} \end{bmatrix}.
    \end{equation*}

    Since the Gaussian kernel is ETP, the matrix $M(\boldsymbol{x^*},\boldsymbol{\bar{x}})$ is invertible, and so such coefficients exist.

    It remains now to establish that $H(x)<1$ away from the target locations.

    By the interpolation conditions, $H-1$ has at least $2K$ zeros, counted with multiplicity.

    Multiplication by $\smash{-e^{x^2}}$ preserves these zeros and their multiplicities.

    Define

    \begin{equation*}
        \tilde\alpha_i=(-\alpha_i+2\beta_i\bar{x}_i)e^{-\bar{x}_i^2}, \qquad \tilde\beta_i=-2\beta_i e^{-\bar{x}_i^2}, \qquad s_i=2\bar{x}_i,
    \end{equation*}

    so that

    \begin{equation*}
        -e^{x^2}(H(x)-1)=\sum_{i=1}^K(\tilde\alpha_i+\tilde\beta_i x)e^{s_i x}+e^{x^2}.
    \end{equation*}

    By Lemma 2.6 of \citet{schiebinger2015superresolutionseparation}, this function, and hence also $H-1$, has at most $2K$ zeros, counted with multiplicity.

    Thus, the prescribed target locations are the only zeros of $H-1$, each with multiplicity exactly two.

    Since $H(x)\to0$ as $x\to\pm\infty$, and $H-1$ cannot change sign at these zeros, it follows that $H(x)<1$ everywhere else.


    We remark that an alternative interpretation of Lemma 2.6 of \citet{schiebinger2015superresolutionseparation} is that the Gaussian kernel, together with its derivatives and the constant function, forms a Chebyshev system.

By Prop.~\ref{prop: Hinterp}, we can construct coefficients $\boldsymbol{\alpha}',\boldsymbol{\beta}'$ such that the function

    $
    H(\cdot) = \sum_{i=1}^A (\alpha'_i k(\cdot,\vartheta_i)+\beta'_i\partial_2k(\cdot,\vartheta_i))
    $
    satisfies $H(\vartheta_i) = 1$, $H'(\vartheta_i) = 0$ for all $i=1,\ldots,A$, and $H(x) < 1$ for all $x\notin\{\vartheta_1,\ldots,\vartheta_A\}$.


    At a stationary point with $F(\mathbf w,\boldsymbol{x})>0$, we must have $\operatorname{supp}(P^*)\not\subseteq\operatorname{supp}(P)$.

    Indeed, if this inclusion held, the target could be represented exactly at the current particle locations, and convexity of the weight optimisation problem would imply that the stationary weights achieve $F(\mathbf w,\boldsymbol{x})=0$.

    Since $H$ equals one at every active particle location and is strictly less than one elsewhere, it follows that

    \begin{align*}
        \int H(x)\,\mathrm dP(x) = \sum_{j=1}^A \varsigma_jH(\vartheta_j)=1, \qquad
        \int H(x)\,\mathrm dP^*(x) <1.
    \end{align*}

    Hence, in particular, 

    \begin{equation}
        \label{Positive test}
        \int H(x)\,\mathrm d(P-P^*)(x)>0.
    \end{equation}

    Meanwhile, the stationarity conditions \eqref{Stationary0redsimp} give

    \begin{align*}
        \int H(x)\,\mathrm d(P-P^*)(x) = \sum_{i=1}^A \left(\alpha'_i\Delta(\vartheta_i)+\beta'_i\Delta'(\vartheta_i)\right)
        = c\sum_{i=1}^A\alpha'_i.
    \end{align*}

    Moreover, by the reproducing property and the interpolation conditions,

    \begin{align*}
        \|H\|_{\mathcal H}^2 &= \begin{bmatrix} (\boldsymbol{\alpha}')^\top & (\boldsymbol{\beta}')^\top \end{bmatrix}M(\boldsymbol{\vartheta},\boldsymbol{\vartheta})\begin{bmatrix} \boldsymbol{\alpha}'\\ \boldsymbol{\beta}' \end{bmatrix}
        = \sum_{i=1}^A\alpha'_i>0,
    \end{align*}

    where $M(\cdot,\cdot)$ is as defined in the proof of Prop.~\ref{prop: Hinterp}.

    Combining these identities with \eqref{Positive test} gives $c>0$.

    Finally, since the Gaussian kernel is strictly positive and bounded above by one, we have $\mu_{P^*}(\vartheta_i)>0$ and $\mu_P(\vartheta_i)\le1$.

    Thus $c=\mu_P(\vartheta_i)-\mu_{P^*}(\vartheta_i)<\mu_P(\vartheta_i)\le1$, establishing $0<c<1$.

First, if $K>1$, it suffices to consider configurations satisfying $\max_j\min_i|x_i-x_j^*|<\frac12\min_{i\neq j}|x_i^*-x_j^*|$, since otherwise the desired separation bound already holds.

    For each target location $x_i^*$, let $\bar x_i$ denote a nearest particle location.

    The separation condition ensures that the $\bar x_i$ are distinct.

    By Prop.~\ref{prop: Hinterp}, we can construct coefficients $\boldsymbol{\alpha},\boldsymbol{\beta}$ such that the function

    $H(\cdot)=\sum_{i=1}^K(\alpha_i k(\cdot,\bar x_i)+\beta_i\partial_2k(\cdot,\bar x_i))$

    satisfies $H(x_i^*)=1$, $H'(x_i^*)=0$ for all $i=1,\ldots,K$, and $H(x)<1$ for all $x\notin\{x_1^*,\ldots,x_K^*\}$.

    Then, as in the proof of Prop.~\ref{prop: cpos}, we have

    \begin{equation*}
        \int H(x)\,\mathrm dP(x)=\sum_{j=1}^N w_jH(x_j)\leq1, \qquad \int H(x)\,\mathrm dP^*(x)=\sum_{i=1}^K w_i^*H(x_i^*)=1.
    \end{equation*}

    Hence, at a spurious stationary point,

    \begin{equation}
        \label{Negative test}
        \int H(x)\,\mathrm d(P-P^*)(x)\leq0.
    \end{equation}

    Meanwhile, Prop.~\ref{prop: simp max principle} gives $\Delta(\bar x_i)=c$ and $\Delta'(\bar x_i)=0$, and therefore

    \begin{equation*}
        \int H(x)\,\mathrm d(P-P^*)(x)=\sum_{i=1}^K\left(\alpha_i\Delta(\bar x_i)+\beta_i\Delta'(\bar x_i)\right)=c\sum_{i=1}^K\alpha_i.
    \end{equation*}

    Since $c>0$ by Prop.~\ref{prop: cpos}, it suffices to establish that $\sum_{i=1}^K\alpha_i>0$ whenever $\boldsymbol{\bar x}$ is sufficiently close to $\boldsymbol{x^*}$.

    At $\boldsymbol{\bar x}=\boldsymbol{x^*}$, the reproducing property and interpolation conditions give

    \begin{equation*}
        \|H\|_{\mathcal H}^2=\begin{bmatrix}\boldsymbol{\alpha}^\top & \boldsymbol{\beta}^\top\end{bmatrix}M(\boldsymbol{x^*},\boldsymbol{x^*})\begin{bmatrix}\boldsymbol{\alpha}\\\boldsymbol{\beta}\end{bmatrix}=\sum_{i=1}^K\alpha_i>0,
    \end{equation*}

    where $M(\cdot,\cdot)$ is as defined in the proof of Prop.~\ref{prop: Hinterp}.

    By continuity of the interpolation coefficients, this positivity persists in a sufficiently small target-dependent neighbourhood of $\boldsymbol{x^*}$.

    Within this neighbourhood, we therefore obtain a contradiction to \eqref{Negative test}.

    Consequently, no spurious stationary point can lie in this neighbourhood.

    We now make the neighbourhood explicit using standard matrix perturbation bounds.

    By the interpolation conditions,

    \begin{equation*}
        \begin{bmatrix}\boldsymbol{\alpha}\\\boldsymbol{\beta}\end{bmatrix}=M(\boldsymbol{x^*},\boldsymbol{\bar x})^{-1}\begin{bmatrix}\mathbf 1\\\mathbf 0\end{bmatrix},
    \end{equation*}

    where

    \begin{equation*}
        M(\boldsymbol{x^*},\boldsymbol{\bar x})=\begin{bmatrix}k(\boldsymbol{x^*},\boldsymbol{\bar x}) & \partial_2k(\boldsymbol{x^*},\boldsymbol{\bar x})\\ \partial_1k(\boldsymbol{x^*},\boldsymbol{\bar x}) & \partial_1\partial_2k(\boldsymbol{x^*},\boldsymbol{\bar x})\end{bmatrix}.
    \end{equation*}

    Thus, writing $e_1=\begin{bmatrix}\mathbf 1\\\mathbf 0\end{bmatrix}$, we have that

    \begin{equation}
        T(\boldsymbol{\bar x})=\sum_{i=1}^K\alpha_i=e_1^\top M(\boldsymbol{x^*},\boldsymbol{\bar x})^{-1}e_1.
    \end{equation}

    We seek an explicit radius $r(P^*)>0$ such that $T(\boldsymbol{\bar x})>0$ whenever $\delta(\boldsymbol{\bar x})=\|\boldsymbol{\bar x}-\boldsymbol{x^*}\|_\infty<r(P^*)$.

    For brevity, write $M(\boldsymbol{\bar x})=M(\boldsymbol{x^*},\boldsymbol{\bar x})$, $M^*=M(\boldsymbol{x^*},\boldsymbol{x^*})$, and $T^*=T(\boldsymbol{x^*})$.

    Notice that $T^*\geq1$.

    Define $E(\boldsymbol{\bar x})=M(\boldsymbol{\bar x})-M^*$ and $q(\boldsymbol{\bar x})=\|(M^*)^{-1}E(\boldsymbol{\bar x})\|_\infty$.

    By the Neumann series, whenever $q(\boldsymbol{\bar x})<1$,

    \begin{equation}
        \|(M^*)^{-1}-M(\boldsymbol{\bar x})^{-1}\|_\infty\leq\frac{q(\boldsymbol{\bar x})}{1-q(\boldsymbol{\bar x})}\|(M^*)^{-1}\|_\infty.
    \end{equation}

    Let $m^{-1}=\|(M^*)^{-1}\|_\infty$.

    Then $q(\boldsymbol{\bar x})\leq m^{-1}\|E(\boldsymbol{\bar x})\|_\infty$.

    By standard derivative bounds for the Gaussian kernel and the mean value theorem,

    \begin{equation*}
        \|E(\boldsymbol{\bar x})\|_\infty\leq6K\delta(\boldsymbol{\bar x}).
    \end{equation*}

    Consequently, Hölder's inequality gives

    \begin{align*}
        |T^*-T(\boldsymbol{\bar x})| &\leq\|e_1\|_1\|(M^*)^{-1}-M(\boldsymbol{\bar x})^{-1}\|_\infty\|e_1\|_\infty
        \leq\frac{6m^{-2}K^2\delta(\boldsymbol{\bar x})}{1-6m^{-1}K\delta(\boldsymbol{\bar x})}.
    \end{align*}

    Since $T^*\geq1$, it suffices to ensure that the final bound is strictly less than one.

    Rearranging the above, we have that

    \begin{equation}
        \delta(\boldsymbol{\bar x})<\frac{1}{6m^{-1}K(m^{-1}K+1)},
    \end{equation}

    which also guarantees $q(\boldsymbol{\bar x})<1$.

    Thus, we can take any $r(P^*)>0$ satisfying

    \begin{equation*}
        r(P^*)<\min\left\{\frac12\min_{i\neq j}|x_i^*-x_j^*|,\frac{1}{6m^{-1}K(m^{-1}K+1)}\right\},
    \end{equation*}

    where the first term is interpreted as $+\infty$ whenever $K=1$.

Let $\rho=P-P^*$ and $\Delta=\mu_P-\mu_{P^*}$.

    By the definition of the MMD, we have that

    \begin{equation*}
        \operatorname{MMD}^2(P,P^*)=\iint k(x,y)\,\mathrm d\rho(x)\,\mathrm d\rho(y)=\int\Delta(x)\,\mathrm d\rho(x).
    \end{equation*}

    Meanwhile, by Bochner's theorem, it follows that

    \begin{equation*}
        \operatorname{MMD}^2(P,P^*)=\frac{1}{(2\pi)^d}\int\hat k(\omega)|\hat\rho(\omega)|^2\,\mathrm d\omega, \qquad \frac{|\hat\Delta(\omega)|^2}{\hat k(\omega)}=\hat k(\omega)|\hat\rho(\omega)|^2.
    \end{equation*}

    Splitting the integral at frequency $\nu$, and using $|\hat\Delta(\omega)|\leq\|\Delta\|_1$ and $|\hat\rho(\omega)|\leq\|\rho\|_{\mathrm{TV}}$, gives

    \begin{align*}
        \operatorname{MMD}^2(P,P^*) &= \frac{1}{(2\pi)^d}\int_{|\omega|\leq\nu}\frac{|\hat\Delta(\omega)|^2}{\hat k(\omega)}\,\mathrm d\omega+\frac{1}{(2\pi)^d}\int_{|\omega|>\nu}\hat k(\omega)|\hat\rho(\omega)|^2\,\mathrm d\omega\\
        &\leq\frac{\|\Delta\|_1^2}{(2\pi)^d}\int_{|\omega|\leq\nu}\frac{1}{\hat k(\omega)}\,\mathrm d\omega+\frac{\|\rho\|_{\mathrm{TV}}^2}{(2\pi)^d}\int_{|\omega|>\nu}\hat k(\omega)\,\mathrm d\omega.
    \end{align*}

    For the one-dimensional Gaussian kernel with $2\sigma^2=1$, we have $\hat k(\omega)=\sqrt{\pi}e^{-\omega^2/4}$.

    Moreover, since $P$ and $P^*$ are probability measures, $\|\rho\|_{\mathrm{TV}}^2\leq4$.

    Substituting into the preceding bound gives

    \begin{align*}
        \operatorname{MMD}^2(P,P^*) &\leq\frac{\|\Delta\|_1^2}{2\pi\sqrt{\pi}}\int_{|\omega|\leq\nu}e^{\omega^2/4}\,\mathrm d\omega+\frac{2}{\sqrt{\pi}}\int_{|\omega|>\nu}e^{-\omega^2/4}\,\mathrm d\omega
        =\frac{\|\Delta\|_1^2}{\pi}\operatorname{erfi}\left(\frac{\nu}{2}\right)+4\operatorname{erfc}\left(\frac{\nu}{2}\right). \qedhere
    \end{align*}

\label{proof of c L1 bound}
    Since $\int_{\mathbb R}\Delta(x)\,\mathrm dx=0$, the positive and negative parts of $\Delta$ have equal integrals, and so

    \begin{equation}
        \label{eq:posdouble}
        \|\Delta\|_1=2\int_{-\infty}^\infty[\Delta]_+.
    \end{equation}

    Write $\mu_P(\cdot)=\sum_i w_i e^{-(x_i-\cdot)^2}$ and $\mu_{P^*}(\cdot)=\int e^{-(x^*-\cdot)^2}\,\mathrm dP^*(x^*)$.

    Let $L,R$ denote the leftmost and rightmost particle locations, and $A,B$ the endpoints of the target support.

    We split the integral above into seven regions:
    \begin{equation}
        (-\infty,L], \qquad [L, L+\delta_L], \qquad [L+\delta_L, A-\varepsilon_L], \qquad [A-\varepsilon_L, B+\varepsilon_R], \qquad [B+\varepsilon_R, R-\delta_R], \qquad [R-\delta_R, R], \qquad [R, \infty),
    \end{equation}
    treating any reversed intervals as empty.

    We impose $\delta_L,\delta_R\geq1/\sqrt{2}$ and define $D_L=A-L$ and $D_R=R-B$.

    If $D_L\leq\delta_L$, we set $\varepsilon_L=0$ and omit the contribution from $[L+\delta_L,A]$, and similarly on the right if $D_R\leq\delta_R$.

    We proceed as follows
    \begin{enumerate}[label={},leftmargin=2em]
        \item $(-\infty,L]$:

        By the maximum principle and the Gaussian tail bound,

        \begin{align*}
            \int_{-\infty}^L[\Delta]_+ &\leq\int_{-\infty}^L\min\{c,\mu_P(x)\}\,\mathrm dx
            \leq\int_{-\infty}^0\min\{c,e^{-x^2}\}\,\mathrm dx
            =c\sqrt{-\log c}+\frac{\sqrt{\pi}}{2}\operatorname{erfc}(\sqrt{-\log c}).
        \end{align*}


        \item $[L,L+\delta_L]$:

        Applying the maximum principle (cf. Prop.~\ref{prop: simp max principle}) gives

        \begin{equation*}
            \int_L^{L+\delta_L}[\Delta]_+\leq c\delta_L.
        \end{equation*}


        \item $[L+\delta_L,A-\varepsilon_L]$:

        Let $X\sim P$ and define $f(x)=xe^{-x^2}$.

        Since $f$ has a single maximum, we have

        \begin{align*}
            \mathbb P(L+\delta_L\leq X\leq A-\varepsilon_L) &\leq\frac{\mathbb E[f(X-L)]}{\min\{f(\delta_L),f(A-\varepsilon_L-L)\}}\\
            &=\frac{\sum_iw_if(x_i-L)}{\min\{f(\delta_L),f(A-\varepsilon_L-L)\}}=\frac{\int f(x^*-L)\,\mathrm dP^*(x^*)}{\min\{f(\delta_L),f(A-\varepsilon_L-L)\}},
        \end{align*}

        where the final equality follows from stationarity at $L$.

        Since $D_L\geq\delta_L\geq1/\sqrt{2}$, the function $f$ is decreasing on $[D_L,\infty)$, and hence $f(x^*-L)\leq f(D_L)$ for every $x^*\in[A,B]$.

        Moreover, since $D_L-\varepsilon_L\geq\delta_L$, we have $f(D_L-\varepsilon_L)\leq f(\delta_L)$.

        Consequently,

        \begin{equation*}
            \mathbb P(L+\delta_L\leq X\leq A-\varepsilon_L)\leq\frac{D_L}{D_L-\varepsilon_L}\exp(-2\varepsilon_LD_L+\varepsilon_L^2).
        \end{equation*}

        It follows that

        \begin{align*}
            \int_{L+\delta_L}^{A-\varepsilon_L}[\Delta]_+ \leq \frac{D_L}{D_L-\varepsilon_L}\exp(-2\varepsilon_LD_L+\varepsilon_L^2)\sqrt{\pi}+2c\sqrt{-\log c}+\sqrt{\pi}\operatorname{erfc}(\sqrt{-\log c}),
        \end{align*}

        where the final two terms account for contributions from particles outside the interval.

        These are obtained by separating the contributions to $\mu_P$ from particles inside and outside the interval, and applying the preceding Gaussian tail estimate to the latter.


        \item $[A-\varepsilon_L,B+\varepsilon_R]$:

        Applying the maximum principle (cf. Prop.~\ref{prop: simp max principle}) again gives

        \begin{equation*}
            \int_{A-\varepsilon_L}^{B+\varepsilon_R}[\Delta]_+\leq c(\varepsilon_L+\varepsilon_R+B-A).
        \end{equation*}

    \end{enumerate}

    The remaining intervals $[B+\varepsilon_R,R-\delta_R]$, $[R-\delta_R,R]$, and $[R,\infty)$ are bounded symmetrically.

    Combining these estimates yields

    \begin{equation}
        \begin{aligned}
            \int_{-\infty}^\infty[\Delta]_+ \leq{}&c(\delta_L+\delta_R+B-A)
            +6\left(c\sqrt{-\log c}+\frac{\sqrt{\pi}}{2}\operatorname{erfc}(\sqrt{-\log c})\right)\\
            &+c\varepsilon_L+\frac{D_L}{D_L-\varepsilon_L}\exp(-2\varepsilon_LD_L+\varepsilon_L^2)\sqrt{\pi}\\
            &+c\varepsilon_R+\frac{D_R}{D_R-\varepsilon_R}\exp(-2\varepsilon_RD_R+\varepsilon_R^2)\sqrt{\pi}.
        \end{aligned}
    \end{equation}

    We now choose $\delta_L=\delta_R=1/\sqrt{2}$ and bound the terms involving $\varepsilon_L$ and $\varepsilon_R$.

    Consider first

    \begin{equation*}
        c\varepsilon_L+\frac{D_L}{D_L-\varepsilon_L}\exp(-2\varepsilon_LD_L+\varepsilon_L^2)\sqrt{\pi}.
    \end{equation*}

    If $D_L^2\leq\frac12-\log c$, we can bound the contribution from $[L+\delta_L,A]$ directly using the maximum principle.

    Since this interval has length $D_L-1/\sqrt{2}$ when nonempty, its contribution is bounded by

    \begin{equation*}
        c\left(D_L-\frac{1}{\sqrt{2}}\right)\leq c\sqrt{-\log c}.
    \end{equation*}

    Otherwise, choose $\varepsilon_L=D_L-\sqrt{D_L^2+\log c}$.

    Then $-2\varepsilon_LD_L+\varepsilon_L^2=\log c$, and $\varepsilon_L\leq\sqrt{-\log c}$.

    Moreover, the ratio

    \begin{equation*}
        \frac{D_L}{D_L-\varepsilon_L}=\frac{D_L}{\sqrt{D_L^2+\log c}}
    \end{equation*}

    is decreasing in $D_L$, and is therefore bounded by its value at $D_L^2=\frac12-\log c$, namely $\sqrt{1-2\log c}$.

    Thus, in either case, the corresponding contribution is bounded by

    \begin{equation*}
        c\sqrt{-\log c}+\sqrt{\pi}c\sqrt{1-2\log c}.
    \end{equation*}

    Applying the same argument to the $\varepsilon_R$ term, and using $B-A\leq D$, gives

    \begin{equation*}
        \int_{-\infty}^\infty[\Delta]_+\leq(\sqrt{2}+D)c+8c\sqrt{-\log c}+3\sqrt{\pi}\operatorname{erfc}(\sqrt{-\log c})+2\sqrt{\pi}c\sqrt{1-2\log c}.
    \end{equation*}

    Combining this with \eqref{eq:posdouble} gives the stated bound.

We begin with the variational characterisation of the MMD, which gives, for any nonzero $q\in\mathcal H$,

    \begin{equation*}
        \operatorname{MMD}(P,P^*)\geq\frac{\left|\sum_iw_iq(x_i)-\sum_jw_j^*q(x_j^*)\right|}{\|q\|_{\mathcal H}}.
    \end{equation*}

    Motivated by related constructions in \citet{decastro2020supermixsparseregularizationmixtures} and \citet{Costarelli2021}, we consider a Jackson-type kernel centred at a target location $x_j^*$,

    \begin{equation*}
        q_j(x)=\left(\frac{\sin(a(x-x_j^*))}{a(x-x_j^*)}\right)^{2m}.
    \end{equation*}

    We first bound its RKHS norm.

    Writing $\hat q_j$ and $\hat k$ for the Fourier transforms of $q_j$ and the Gaussian kernel, respectively, we have that

    \begin{equation*}
        \|q_j\|_{\mathcal H}^2=\frac{1}{2\pi}\int_{\mathbb R}\frac{|\hat q_j(\omega)|^2}{\hat k(\omega)}\,\mathrm d\omega.
    \end{equation*}

    Since $\hat k(\omega)=\sqrt{\pi}e^{-\omega^2/4}$, $\|\hat q_j\|_\infty\leq\pi/a$, and $\hat q_j$ is supported on $[-2ma,2ma]$ as the $2m$-fold convolution of a box function, we then obtain

    \begin{equation*}
        \|q_j\|_{\mathcal H}^2\leq\frac{\pi}{a^2}\operatorname{erfi}(ma)\leq\frac{\pi}{a^2}e^{m^2a^2}.
    \end{equation*}

    Thus $\|q_j\|_{\mathcal H}\leq C(a,m)$, with the bound independent of $j$ by translation invariance of the Gaussian kernel.

    We next use the fact that $q_j(x_j^*)=1$ and $q_j\geq0$ to obtain

    \begin{equation*}
        \sum_k w_k^*q_j(x_k^*)\geq w_j^*.
    \end{equation*}

    Suppose the target atom $x_j^*$ is missed by a neighbourhood of radius $r$.

    Then $q_j(x_i)\leq(ar)^{-2m}$ for every particle location $x_i$, and hence, since the weights sum to one,

    \begin{equation*}
        \sum_iw_iq_j(x_i)\leq(ar)^{-2m}.
    \end{equation*}

    Consequently, letting $w^*=\min_jw_j^*$, due to the variational bound we arrive at

    \begin{equation*}
        \operatorname{MMD}(P,P^*)\geq\frac{[w_j^*-(ar)^{-2m}]_+}{\|q_j\|_{\mathcal H}}\geq\frac{[w^*-(ar)^{-2m}]_+}{C(a,m)}. \qedhere
    \end{equation*}

Consider an interval of radius $r$ around a particle location $x_i$, and let $p_{i,r}=P([x_i-r,x_i+r])$.

    Since $\mu_P(x_i)=\mu_{P^*}(x_i)+c\geq c$, we have that

    \begin{equation*}
        \mu_P(x_i)=\int e^{-(x_i-y)^2}\,\mathrm dP(y)\leq p_{i,r}+(1-p_{i,r})e^{-r^2}.
    \end{equation*}

    Thus, in particular, 

    \begin{equation*}
        p_{i,r}\geq\frac{c-e^{-r^2}}{1-e^{-r^2}}=:p_r.
    \end{equation*}

    Now place an interval of radius $r$ around each particle location, and let $C_1,\ldots,C_S$ denote the connected components of their union.

    Within each component, construct a maximal $2r$-separated packing by selecting particle locations from left to right, choosing each successive location as soon as it lies more than $2r$ from the preceding one.

    Let $B_s$ denote the number of selected locations in component $C_s$.

    Since the corresponding intervals are disjoint and each has probability mass at least $p_r$, we have

    \begin{equation*}
        1\leq S\leq\sum_{s=1}^S B_s\leq\frac{1}{p_r}.
    \end{equation*}

    Moreover, by maximality of the packing, each component $C_s$ has diameter at most $4B_sr$.

    Let $d\leq r$ satisfy $c>e^{-d^2}$.

    For each component $C_s$, choose $z_0$ at distance $r$ to the left of its leftmost particle location.

    By construction, $z_0$ lies at distance at least $d$ from every particle location.

    Hence $\mu_P(z_0)\leq e^{-d^2}$, and therefore, recalling that $h=\Delta-c$,

    \begin{equation*}
        |h(z_0)|=|c-\Delta(z_0)|\geq c-e^{-d^2}.
    \end{equation*}

    Let $\bar h_{z_0}$ denote the analytic continuation of $h$ to the complex plane, recentred at $z_0$.

    As in the proof of Theorem~\ref{thm: relaxepsbound}, following the approach of \citet{gröchenig2018sharpresultssamplingderivatives}, we have

    \begin{equation*}
        |\bar h_{z_0}(x+iy)|\leq c+2e^{y^2}\leq(c+2)e^{y^2}.
    \end{equation*}

    Now let $\delta>1$ and $R_s\geq(4B_s-1)r$, so that the disc of radius $R_s$ centred at $z_0$ contains all particle locations in $C_s$.

    Applying Prop.~\ref{prop: jenzerocount} with $A_f=c+2$ and $B_f=1$ gives

    \begin{equation*}
        \mathbf n_{\bar h_{z_0}}(R_s)\leq\frac{\log\left(\frac{c+2}{c-e^{-d^2}}\right)+\frac12\delta^2R_s^2}{\log\delta}.
    \end{equation*}

    Since every distinct particle location contributes a zero of multiplicity two, summing over the components gives at least $2A$ zeros, counted with multiplicity.

    Consequently, using the same $\delta$ for every component, we obtain

    \begin{equation*}
        A\leq\frac{S\log\left(\frac{c+2}{c-e^{-d^2}}\right)+\frac12\delta^2\sum_{s=1}^S R_s^2}{2\log\delta}.
    \end{equation*}

    We now choose $\delta=\sqrt e$, $d=r$, $r=\sqrt{\log(2)-\log c}$, and $R_s=(4B_s-1)r$.

    We then have that

    $
        \sum_{s=1}^S R_s^2=r^2\sum_{s=1}^S(4B_s-1)^2\leq r^2(4\sum_{s=1}^S B_s-S)^2\leq r^2(\frac4{p_r}-1)^2.
    $

    With these choices, $p_r=c/(2-c)$, so $S\leq 1/p_r=(2-c)/c$.

    Substituting these bounds into the preceding estimate gives

    \begin{equation*}
        A\leq\frac{2-c}{c}\log\left(\frac{2(c+2)}{c}\right)+\frac e2\left(\frac{8-5c}{c}\right)^2\log\left(\frac2c\right). \qedhere
    \end{equation*}

